String code  = req.getParameter("code");
String state = req.getParameter("state");
if (!state.equals(session.getAttribute("oauth_state"))) {
    throw new SecurityException("bad state");
}
Tokens t = authServer.exchangeCode(code, session.getAttribute("code_verifier"));
String userId = decodeJwt(t.accessToken()).get("sub");
session.setAttribute("user", userId);
